from autor import Lectie, Unitate, grafic

REF = "Manual Art Klett, clasa a VII-a, ediția 2024 (manuale.edu.ro), lecția „{}”"
S_CO2 = ["NOAA Global Monitoring Laboratory – Trends in Atmospheric Carbon Dioxide (Mauna Loa)", "NASA Climate – Carbon Dioxide vital sign"]
S_TEMP = ["WMO – State of the Global Climate 2024", "Copernicus Climate Change Service – Global Climate Highlights 2024"]
S_PARIS = ["UNFCCC – The Paris Agreement", "Comisia Europeană – Acordul de la Paris"]
S_MONTREAL = ["UNEP Ozone Secretariat – The Montreal Protocol", "WMO/UNEP – Scientific Assessment of Ozone Depletion 2022"]


def unitate():
    # ================================================================ S33 Componentele mediului
    M = Lectie(7, "VII-S33-componentele-mediului-inconjurator-relatiile", "Componentele mediului înconjurător și relațiile dintre ele",
               "Ce se întâmplă cu un râu dacă se taie pădurea de lângă izvorul lui?",
               [("Componentele", "Mediul înconjurător cuprinde componente naturale (aerul, apa, relieful și rocile, solul, plantele, animalele) și componente create de om (așezări, drumuri, fabrici, terenuri agricole).\nToate sunt legate între ele: o schimbare într-o componentă le influențează pe celelalte."),
                ("Relații", "Clima influențează apele, vegetația, solurile. Relieful influențează clima (altitudinea) și drumul apelor. Vegetația protejează solul și reține apa. Animalele depind de plante. Oamenii folosesc toate componentele și le modifică.\nUn ecosistem este un loc în care viețuitoarele și mediul lor fizic formează un întreg: o pădure, un lac, o deltă."),
                ("Echilibrul", "În natură există un echilibru. Când omul intervine prea mult (defrișări, poluare, vânat excesiv, specii invazive), echilibrul se strică, iar efectele se pot transmite în lanț.")],
               stiaica="Când lupii au fost readuși în Parcul Național Yellowstone (SUA), în 1995, cerbii au început să evite văile râurilor; vegetația de pe maluri s-a refăcut, iar malurile au devenit mai stabile.",
               ref=REF.format("Componentele mediului înconjurător și relațiile dintre acestea"))
    M.a(1, "1.2", "Ce cuprinde mediul înconjurător?", "componente naturale (aer, apă, sol, relief, plante, animale) și componente create de om", ["doar orașele", "doar pădurile", "doar oceanele"], "Mediul e tot ce ne înconjoară.")
    M.s(2, "1.2", "Asociază componenta cu tipul ei.", [("solul", "componentă naturală"), ("autostrada", "componentă creată de om"), ("roua", "fenomen natural"), ("lacul de acumulare", "apă amenajată de om")], "Natural și antropic.")
    M.a(2, "1.2", "Ce este un ecosistem?", "un loc în care viețuitoarele și mediul lor fizic formează un întreg", ["un tip de rocă", "o hartă", "un oraș"], "Exemple: pădurea, lacul, delta.")
    M.a(2, "2.3", "Ce se întâmplă cu un râu dacă se taie pădurea din bazinul lui?", "crește riscul de viituri și apa devine mai tulbure, din cauza eroziunii", ["râul devine mai curat", "râul dispare imediat", "nu se întâmplă nimic"], "Pădurea reține apa și solul.")
    M.a(2, "2.3", "Cum influențează relieful clima?", "pe munte e mai frig și plouă mai mult decât în câmpie", ["nu o influențează", "pe munte e mai cald", "câmpia e mereu mai rece"], "Altitudinea modifică temperatura și precipitațiile.")
    M.o(3, "2.3 3.1 4.2", "Ordonează efectele în lanț ale tăierii unei păduri de pe pantă.", ["se taie pădurea", "ploile spală solul", "râul primește mult mâl", "albia se colmatează", "cresc inundațiile în aval"], "Efecte în lanț", "O schimbare produce altele.")
    M.o(3, "2.3 3.1 4.2", "Ordonează efectele poluării unui lac cu îngrășăminte.", ["îngrășămintele ajung în lac", "algele se înmulțesc foarte mult", "algele moarte consumă oxigenul", "peștii mor"], "Efecte în lanț", "Fenomenul se numește eutrofizare.")
    M.a(2, "3.3", "Ce rol au plantele în mediu?", "produc oxigen, protejează solul, rețin apa, dau hrană și adăpost", ["nu au niciun rol", "poluează aerul", "usucă solul"], "Plantele sunt baza ecosistemelor.")
    M.a(2, "4.3", "Ce se întâmplă dacă dispar prădătorii dintr-un ecosistem?", "ierbivorele se înmulțesc prea mult și distrug vegetația", ["nu se întâmplă nimic", "plantele cresc mai bine mereu", "dispar și plantele imediat"], "Exemplul lupilor din Yellowstone.")
    M.a(2, "4.4", "Ce sunt speciile invazive?", "specii aduse dintr-o altă regiune, care se înmulțesc și dăunează speciilor locale", ["specii pe cale de dispariție", "plante de cameră", "animale domestice obișnuite"], "Exemple: iepurii în Australia, ambrozia în Europa.")
    M.adev(2, "1.2", "Componentele mediului nu se influențează între ele.", False, "Fals: sunt strâns legate.")
    M.adev(2, "2.3", "Delta Dunării e un ecosistem.", True, "Adevărat: un ecosistem de zonă umedă, foarte bogat.")
    M.l(2, "1.2", "Completează.", "Un loc unde viețuitoarele și mediul formează un întreg se numește [ecosistem]; specia adusă din altă parte care dăunează se numește specie [invazivă].", ["habitat", "endemică"], "Ecosistem, invazivă.")
    M.l(2, "2.3", "Completează.", "Pădurea [reține] apa și protejează [solul] de eroziune.", ["evaporă", "aerul"], "Rolul pădurii.")
    M.p(2, "2.3", "Atinge pe harta României Delta Dunării, un ecosistem protejat.", "romania", 45.1, 29.3, "Delta Dunării", 50, "Delta e Rezervație a Biosferei.")
    M.p(3, "2.3", "Atinge pe hartă Parcul Național Yellowstone (SUA).", "lume", 44.6, -110.5, "Yellowstone", 400, "Yellowstone, înființat în 1872, e primul parc național din lume.")
    M.g(3, "2.3 4.1", "Graficul arată numărul de cerbi și lupi într-un parc imaginar. Ce s-a întâmplat după revenirea lupilor?", grafic("profil", "Număr de cerbi într-un parc imaginar", [("anul 0", 18), ("anul 5 (vin lupii)", 17), ("anul 10", 12), ("anul 15", 9), ("anul 20", 8)], "mii"), "numărul cerbilor a scăzut și s-a stabilizat", ["a crescut", "a rămas neschimbat", "cerbii au dispărut"], "Prădătorii refac echilibrul.")
    M.a(3, "4.3", "Compară un ecosistem natural cu un câmp cultivat cu o singură plantă.", "ecosistemul natural are multe specii și e mai stabil; monocultura are puține specii și e mai vulnerabilă", ["sunt identice", "monocultura e mai bogată", "ecosistemul natural nu are plante"], "Biodiversitatea dă stabilitate.")
    M.a(2, "3.3", "Ce componentă a mediului e esențială pentru agricultură?", "solul fertil (și apa)", ["asfaltul", "zgomotul", "fumul"], "Hrana noastră crește din sol.")
    M.a(2, "2.3", "Cum influențează clima solurile?", "clima decide ce plante cresc și cât de repede se formează humusul", ["nu le influențează", "solurile decid clima", "doar relieful contează"], "Cernoziomul s-a format sub stepă, în climă temperată.")
    M.a(2, "4.4", "Ce înseamnă „arie protejată”?", "un teritoriu unde natura e ocrotită prin lege", ["un oraș nou", "o zonă industrială", "o parcare"], "Parcuri naționale, rezervații, situri Natura 2000.")
    M.a(2, "4.4", "Ce este rețeaua Natura 2000?", "rețeaua europeană de arii protejate pentru specii și habitate", ["o rețea de autostrăzi", "un program TV", "o rețea de telefonie"], "România are sute de situri Natura 2000.")
    M.d(2, "2.3", "Ce zonă umedă protejată din România e marcată pe hartă?", "romania", 45.1, 29.3, "Delta Dunării", ["Lacul Razim", "Balta Brăilei", "Lacul Snagov"], "Delta are peste 300 de specii de păsări.")
    M.a(2, "3.3", "Ce legătură e între albine și agricultură?", "albinele polenizează multe culturi; fără ele, recoltele scad", ["albinele distrug culturile", "nu e nicio legătură", "albinele produc îngrășăminte"], "Polenizatorii sunt esențiali.")
    M.a(3, "4.4", "De ce o mlaștină desecată poate duce la inundații în aval?", "mlaștina reținea apa ca un burete; fără ea, apa ajunge repede în râu", ["mlaștina producea ploaie", "desecarea răcește clima", "fără motiv"], "Zonele umede protejează contra inundațiilor.")
    M.a(2, "1.2", "Ce componentă creată de om modifică cel mai mult cursul unui râu?", "barajul", ["un copac", "o pasăre", "o piatră"], "Barajul transformă râul în lac.")
    M.a(2, "4.4", "Ce poate face o școală pentru ecosistemul local?", "plantează specii locale și amenajează un colț pentru insecte polenizatoare", ["taie copacii din curte", "betonează curtea", "aruncă deșeurile în pârâu"], "Acțiuni concrete.")
    M.a(2, "1.2", "Ce înseamnă echilibru ecologic?", "starea în care componentele unui ecosistem se mențin în proporții stabile", ["dispariția tuturor speciilor", "un singur tip de plantă", "lipsa apei"], "Echilibrul poate fi stricat de om.")
    M.a(3, "2.3", "Cum influențează orașul clima locală?", "orașul e mai cald decât împrejurimile (insulă de căldură), din cauza betonului și asfaltului", ["orașul e mereu mai rece", "orașul nu influențează clima", "orașul aduce zăpadă vara"], "Spațiile verzi reduc insula de căldură.")
    M.a(2, "3.3", "Ce sunt speciile endemice?", "specii care trăiesc doar într-un anumit loc", ["specii aduse din altă parte", "specii domestice", "specii dispărute"], "Exemple: lemurii din Madagascar, garofița Pietrei Craiului.")

    # ================================================================ S34 Degradarea mediului. Schimbări globale
    D = Lectie(7, "VII-S34-degradarea-mediului-inconjurator-problema", "Degradarea mediului – o problemă a lumii contemporane",
               "Este încălzirea globală reală și ce putem face?",
               [("Forme de degradare", "Poluarea aerului (fabrici, transport, încălzire), a apei (ape uzate, plastic, petrol) și a solului (deșeuri, pesticide).\nDefrișările (Amazonia, Indonezia, Africa centrală), deșertificarea (Sahel), pierderea biodiversității, epuizarea resurselor, eroziunea solului."),
                ("Schimbări globale", "Arderea combustibililor fosili a crescut concentrația de dioxid de carbon din atmosferă: de la aproximativ 280 ppm înainte de era industrială la peste 420 ppm azi, după măsurătorile NOAA. Efectul de seră s-a intensificat, iar temperatura medie a planetei a crescut. După WMO, 2024 a fost cel mai cald an înregistrat, cu aproximativ 1,55 °C peste nivelul preindustrial.\nUrmări: topirea ghețarilor, creșterea nivelului mării, valuri de căldură, secete, ploi torențiale, incendii."),
                ("Soluții", "Acordul de la Paris (2015): statele s-au angajat să limiteze încălzirea mult sub 2 °C, încercând 1,5 °C. Protocolul de la Montreal (1987) a interzis substanțele care distrugeau stratul de ozon, iar acesta se reface.\nSoluții: energie regenerabilă, eficiență energetică, transport public, reciclare, protejarea pădurilor, agricultură durabilă.")],
               stiaica="Datorită Protocolului de la Montreal, stratul de ozon se reface; oamenii de știință estimează că deasupra Antarcticii va reveni la nivelul din 1980 în jurul anului 2066.",
               ref=REF.format("Degradarea mediului înconjurător, o problemă a lumii contemporane"))
    D.s(1, "1.2", "Asociază forma de degradare cu un exemplu.", [("defrișarea", "tăierea pădurii amazoniene"), ("deșertificarea", "înaintarea deșertului în Sahel"), ("poluarea apei", "plasticul din oceane"), ("poluarea aerului", "smogul din marile orașe")], "Forme de degradare.")
    D.a(1, "2.3", "Ce gaz a crescut cel mai mult în atmosferă din cauza arderii combustibililor fosili?", "dioxidul de carbon", ["oxigenul", "azotul", "argonul"], "Concentrația a trecut de 420 ppm.", surse=S_CO2)
    D.a(1, "3.3", "Ce concentrație de dioxid de carbon avea aerul înainte de era industrială?", "aproximativ 280 ppm", ["aproximativ 4 200 ppm", "aproximativ 28 ppm", "0 ppm"], "Azi depășește 420 ppm.", surse=S_CO2)
    D.a(2, "1.2", "Ce este efectul de seră?", "reținerea căldurii în atmosferă de către unele gaze, ca într-o seră", ["răcirea Pământului de către Lună", "formarea norilor", "lumina stelelor"], "Natural e util; accentuat de om încălzește planeta.")
    D.a(2, "2.3", "Care a fost cel mai cald an înregistrat, după WMO?", "2024", ["1950", "1990", "2005"], "Aproximativ 1,55 °C peste nivelul preindustrial.", surse=S_TEMP)
    D.s(2, "4.3", "Asociază urmarea încălzirii cu regiunea.", [("topirea ghețarilor", "Alpi și Himalaya"), ("creșterea nivelului mării", "Maldive și Tuvalu"), ("secetele", "Sahel și sudul Europei"), ("incendiile de vegetație", "Australia și California")], "Efectele schimbărilor climatice.")
    D.a(2, "4.4", "Ce prevede Acordul de la Paris (2015)?", "limitarea încălzirii globale mult sub 2 °C, încercând 1,5 °C", ["oprirea tuturor fabricilor", "construirea de noi centrale pe cărbune", "nimic concret"], "A fost semnat de aproape toate statele lumii.", surse=S_PARIS)
    D.a(2, "4.4", "Ce a interzis Protocolul de la Montreal (1987)?", "substanțele care distrugeau stratul de ozon (freonii)", ["petrolul", "plasticul", "mașinile"], "Stratul de ozon se reface.", surse=S_MONTREAL)
    D.a(2, "4.4", "Care dintre acestea e o soluție contra încălzirii globale?", "energia solară și eoliană", ["mai multe centrale pe cărbune", "tăierea pădurilor", "arderea deșeurilor"], "Energia regenerabilă nu emite dioxid de carbon.")
    D.a(2, "1.2", "De ce crește nivelul mării?", "se topesc ghețarii de pe uscat și apa se dilată când se încălzește", ["plouă mai mult pe mare", "râurile sunt mai lungi", "Luna e mai aproape"], "Două cauze principale.")
    D.p(2, "2.3", "Atinge pe hartă o regiune afectată de deșertificare: Sahelul.", "lume", 15, 5, "Sahel", 800, "Sahelul e la sud de Sahara.")
    D.p(3, "2.3", "Atinge pe hartă Paris, orașul în care s-a semnat acordul climatic din 2015.", "lume", 48.86, 2.35, "Paris", 300, "Acordul de la Paris.", surse=S_PARIS)
    D.adev(2, "2.3", "Concentrația de dioxid de carbon din atmosferă a crescut mult după începutul erei industriale.", True, "Adevărat: de la ~280 la peste 420 ppm.", surse=S_CO2)
    D.adev(2, "4.4", "Stratul de ozon nu se mai poate reface niciodată.", False, "Fals: datorită Protocolului de la Montreal, se reface.", surse=S_MONTREAL)
    D.l(2, "4.4", "Completează.", "Acordul climatic din 2015 s-a semnat la [Paris]; protocolul pentru stratul de ozon s-a semnat la [Montreal].", ["Kyoto", "Londra"], "Paris, Montreal.")
    D.l(2, "1.2", "Completează.", "Gazul care a crescut cel mai mult din cauza arderilor este [dioxidul de carbon]; el intensifică efectul de [seră].", ["oxigenul", "ozon"], "CO₂, efect de seră.")
    D.g(3, "2.3 4.1", "Graficul arată concentrația de dioxid de carbon măsurată la Mauna Loa (valori rotunjite). Ce observi?", grafic("profil", "CO₂ în atmosferă, Mauna Loa (valori rotunjite)", [("1960", 317), ("1980", 339), ("2000", 370), ("2010", 390), ("2024", 424)], "ppm", "NOAA Global Monitoring Laboratory"), "concentrația crește din ce în ce mai repede", ["a scăzut", "a rămas aceeași", "a crescut doar până în 1980"], "Curba Keeling.", surse=S_CO2)
    D.g(3, "2.3 4.3 4.1", "În același grafic, cu cât a crescut concentrația între 1960 și 2024?", grafic("profil", "CO₂ în atmosferă, Mauna Loa (valori rotunjite)", [("1960", 317), ("1980", 339), ("2000", 370), ("2010", 390), ("2024", 424)], "ppm", "NOAA Global Monitoring Laboratory"), "cu aproximativ 107 ppm", ["cu 7 ppm", "cu 424 ppm", "cu 1 000 ppm"], "424 − 317 = 107.", surse=S_CO2)
    D.a(3, "4.3", "Compară cauzele deșertificării din Sahel cu cele ale defrișării din Amazonia.", "în Sahel: secete și pășunat excesiv; în Amazonia: tăierea pădurii pentru pășuni și culturi", ["sunt cauzate de vulcani", "sunt identice", "nu au cauze umane"], "Ambele sunt accentuate de om.")
    D.a(2, "4.4", "Ce poți face tu pentru a reduce amprenta de carbon?", "mergi pe jos sau cu bicicleta, economisești energia, reduci risipa de mâncare", ["lași lumina aprinsă", "folosești mașina pentru 200 m", "arunci mâncarea"], "Obiceiurile zilnice contează.")
    D.a(2, "1.2", "Ce înseamnă „amprentă de carbon”?", "cantitatea de gaze cu efect de seră produsă de activitățile unei persoane sau ale unei țări", ["urma lăsată de un pantof", "un tip de cărbune", "o hartă"], "Se măsoară în tone de CO₂ pe an.")
    D.a(2, "4.4", "Ce înseamnă „economie verde”?", "o economie care reduce poluarea și folosește resursele cu grijă", ["o economie care produce doar vopsea verde", "o economie fără energie", "o economie bazată pe cărbune"], "Locuri de muncă în energie curată, reciclare.")
    D.d(2, "2.3", "Ce pădure, amenințată de defrișări, e marcată pe hartă?", "lume", -4, -62, "pădurea amazoniană", ["pădurea Congo", "taigaua", "pădurea Borneo"], "Amazonia e cea mai mare pădure tropicală.")
    D.a(3, "4.4", "De ce problemele de mediu trebuie rezolvate prin cooperare internațională?", "poluarea și clima nu țin cont de granițe", ["pentru că fiecare țară e izolată", "pentru că nu există granițe", "nu trebuie rezolvate"], "Atmosfera și oceanele sunt comune.")
    D.a(2, "4.4", "Ce înseamnă „dezvoltare durabilă”?", "dezvoltare care satisface nevoile de azi fără să compromită viitorul", ["dezvoltare cu orice preț", "oprirea oricărei dezvoltări", "exploatare maximă a resurselor"], "Definiția din Raportul Brundtland (1987).")
    D.a(2, "2.3", "Ce înseamnă „insula de plastic” din Pacific?", "o zonă imensă în care curenții adună deșeuri de plastic", ["o insulă construită din plastic pentru turiști", "o insulă vulcanică", "un atol"], "Plasticul se rupe în microplastice.")
    D.a(2, "4.4", "Ce face poluarea cu plastic animalelor marine?", "le rănește sau le omoară când îl înghit sau se încurcă în el", ["le hrănește", "le ajută să înoate", "nu are efect"], "Țestoasele confundă pungile cu meduzele.")
    D.a(3, "4.3", "De ce încălzirea globală poate produce și ploi mai puternice?", "aerul mai cald poate reține mai mulți vapori de apă, care cad apoi ca ploi torențiale", ["pentru că se răcește oceanul", "pentru că dispar norii", "fără motiv"], "Extremele devin mai frecvente.")
    D.a(2, "4.4", "Ce înseamnă „reducere, refolosire, reciclare”?", "consumi mai puțin, folosești lucrurile de mai multe ori și reciclezi ce nu mai poți folosi", ["cumperi mai mult", "arunci tot", "arzi deșeurile"], "Regula celor trei R.")
    D.a(2, "4.4", "Ce poate face orașul tău pentru mediu?", "colectare selectivă, transport public, spații verzi, iluminat eficient", ["mai multe gropi de gunoi neecologice", "tăierea parcurilor", "închiderea transportului public"], "Soluții locale.")

    return Unitate(7, "u5-mediu.json", "Elemente de geografia mediului înconjurător").add(M, D)
